from base.exceptions import EntityBadRequestError, InsufficientPermissionsErrorfrom base.service import BaseServicefrom models.container import Containerfrom models.container import ContainerTypefrom models.topic_offer import TopicOffer, TopicOfferStatusfrom repositories.container import ContainerRepositoryfrom schemas.topic import AddTopicByOffer, CreateTopicfrom services.container import ContainerServicefrom services.topic_offer import TopicOfferServicefrom DTO.container import ContainerDTO, ContainerWithAuthorDTOfrom sqlalchemy.ext.asyncio import AsyncSessionfrom utils.post import generate_slugfrom utils.container import ContainerSearchParamsfrom helpers.search import Paginationfrom dataclasses import asdictclass TopicService(BaseService[Container, ContainerRepository, ContainerDTO]):    def __init__(self, session: AsyncSession):        super().__init__(Container, session, ContainerRepository)        self.offer_service = TopicOfferService(session)        self.container_service = ContainerService(session)    async def create_topic(            self,            topic: CreateTopic,            author_id: int,    ) -> ContainerDTO:        topic.slug = generate_slug(topic.slug)        await self.check_already_exists(slug=topic.slug, type=ContainerType.topic)        topic = await self.container_service.create_item(            **topic.dict(),            type=ContainerType.topic,            author_id=author_id        )        return await self.container_service.repository.get_full_container(topic.id)    async def search_topic(            self, pagination: Pagination,            search: ContainerSearchParams    ) -> list[ContainerWithAuthorDTO]:        return await self.container_service.search_container(            type_=ContainerType.topic, search=search, pagination=pagination        )    # async def create_topic_from_offer(    #         self,    #         topic_offer: TopicOffer,    #         process: AddTopicByOffe